import {
  USER_DETAILS_JOURNEY_BOXES,
  USER_DETAILS_DATA,
  USER_DETAILS_JOURNEY_OPTIONS,
  USER_DETAILS_JOURNEY_GRAPH,
  USER_DETAILS_LOADER,
  USER_DETAILS_JOURNEY_GRAPH_LOADER,
  USER_DETAILS_JOURNEY_BOXES_LOADER,
  USER_DETAILS_LOCATION,
  USER_ANALYTICS_BOXES,
  USER_ANALYTICS_GRAPH,
  SELECTED_TAB,
  USER_GROUPING_OPTIONS,
  USER_GROUP_LIST,
  USER_AGGREGATION_LIST,
  USER_PLOT_OPTIONS,
  USER_GRAPH_LOADER,
  RESET_ALL_FILTERS,
  USER_TOP_EVENT_STAT_BOX,
  USER_ISSUES_STAT_BOX,
  USER_BOX_FILTER,
  USER_TOP_SCREEN_DURATION_BOX,
  USER_SELECTED_BOX,
  RESET_ALL_BOX,
  USER_LABEL_DISPLAY,
  USER_ANALYTICS_BOXES_PREV,
  USER_TOP_SCREEN_DURATION_BOX_PREV,
  USER_TOP_EVENT_STAT_BOX_PREV,
  USER_ISSUES_STAT_BOX_PREV,
} from 'Utils/constants/reduxActionTypes/userList'
import { userGroupList, userAggregationList, userSelectedBox, userSeriesPlotOptions } from 'Utils/constants/index'
import { LOG_OUT } from '../../types'

export const userDetailReducer = (
  state = { loader: false, data: {}, chooseIndex: null, labelDisplay: false },
  action
) => {
  switch (action.type) {
    case USER_DETAILS_JOURNEY_BOXES:
      return {
        ...state,
        userJourneyBoxes: action.data,
      }
    case USER_DETAILS_JOURNEY_OPTIONS:
      return {
        ...state,
        userJourneyOptions: action.data,
      }
    case USER_DETAILS_JOURNEY_GRAPH:
      return {
        ...state,
        userJourneyGraphData: action.data,
      }
    case USER_DETAILS_JOURNEY_GRAPH_LOADER:
      return {
        ...state,
        loaderForGraph: action.loaderForGraph,
      }
    case USER_DETAILS_DATA:
      return {
        ...state,
        data: action.data,
      }
    case USER_DETAILS_LOADER:
      return {
        ...state,
        loader: action.loader,
      }
    case USER_DETAILS_JOURNEY_BOXES_LOADER:
      return {
        ...state,
        loaderForBoxes: action.loaderForBoxes,
      }
    case USER_DETAILS_LOCATION:
      return {
        ...state,
        locationData: action.data,
      }
    case USER_LABEL_DISPLAY:
      return {
        ...state,
        labelDisplay: action.data,
      }
    case LOG_OUT:
      return []
    default:
      return state
  }
}
export const userAnalyticsReducer = (
  state = {
    selectedBox: userSelectedBox,
    selectedTab: 'usersList',
    aggregation_list: userAggregationList,
    group_list: userGroupList,
    series_plot_options: userSeriesPlotOptions,
    graphData: null,
    statsBoxes: {},
    groupingOptions: null,
    graphLoader: false,
    topScreenBox: {},
    topEventStatBox: {},
    issuesStatBox: {},
    topScreenDurationBox: {},
    selectedBoxFilter: [],
    prevStatsBoxes: {},
    prevTopEventStatBox:{},
    prevIssuesStatBox:{},
    prevTopScreenDurationBox:{},
  },
  action
) => {
  switch (action.type) {
    case USER_SELECTED_BOX:
    return {
      ...state,
      selectedBox: action.selectedBox
    }
    case USER_ANALYTICS_BOXES:
      return {
        ...state,
        statsBoxes: action.statsBoxes,
      }
    case USER_ANALYTICS_GRAPH:
      return {
        ...state,
        graphData: action.graphData,
      }
    case SELECTED_TAB:
      return {
        ...state,
        selectedTab: action.selectedTab,
      }
    case USER_GROUPING_OPTIONS:
      return {
        ...state,
        groupingOptions: action.groupingOptions,
      }
    case USER_AGGREGATION_LIST:
      return {
        ...state,
        aggregation_list: action.aggList,
      }
    case USER_GROUP_LIST:
      return {
        ...state,
        group_list: action.grpList,
      }
    case USER_PLOT_OPTIONS:
      return {
        ...state,
        series_plot_options: action.plotOptions,
      }
    case USER_GRAPH_LOADER:
      return {
        ...state,
        graphLoader: action.graphLoader,
      }
    case USER_TOP_SCREEN_DURATION_BOX:
      return {
        ...state,
        topScreenDurationBox: action.topScreenDurationBox,
      }
    case USER_TOP_EVENT_STAT_BOX:
      return {
        ...state,
        topEventStatBox: action.topEventStatBox,
      }
    case USER_ISSUES_STAT_BOX:
      return {
        ...state,
        issuesStatBox: action.issuesStatBox,
      }
    case USER_BOX_FILTER:
      return {
        ...state,
        selectedBoxFilter: action.selectedBoxFilter
      }
    case USER_ANALYTICS_BOXES_PREV:
      return {
        ...state,
        prevStatsBoxes: action.statsBoxesPrev
      }
    case USER_TOP_SCREEN_DURATION_BOX_PREV:
      return {
        ...state,
        prevTopScreenDurationBox: action.topScreenDurationBoxPrev
      }
    case USER_TOP_EVENT_STAT_BOX_PREV:
      return {
        ...state,
        prevTopEventStatBox: action.topEventStatBoxPrev
      }
    case USER_ISSUES_STAT_BOX_PREV:
      return {
        ...state,
        prevIssuesStatBox: action.issuesStatBoxPrev
      }
    case RESET_ALL_FILTERS:
      return {
        ...state,
        series_plot_options: { type: 'bar', inverted: false },
        aggregation_list: [
          { attribute: 'count', operator: '', table: 'appuser' },
        ],
        group_list: [
          {
            attribute: 'user_appversion',
            categoryTitle: 'Device',
            display: 'app version',
            max_group_number: 50,
            table: 'appuser',
            type: 'str',
          },
        ],
        selectedBox: {
          attrOfSmallBox: 'Total',
          mainKey: 'Users',
          tooltip: 'Total number of users that used the app',
          graph_info: 'Number of total users',
          activeIndex: 1,
        },
        topScreenBox: {},
        topEventStatBox: {},
        frustrationStatBox: {},
        issuesStatBox: {},
        topScreenDurationBox: {}
      };
      case RESET_ALL_BOX: {
        return {
          ...state,
          topScreenBox: {},
          topEventStatBox: {},
          frustrationStatBox: {},
          issuesStatBox: {},
          statsBoxes: {},
          topScreenDurationBox: {},
          prevStatsBoxes: {},
          prevTopScreenDurationBox: {},
          prevIssuesStatBox: {}
        };
      }
    case LOG_OUT:
      return []
    default:
      return state
  }
}
