export const postErrorHandle = async (dispatch, action, res, data) => {
  const orgId = data?.orgId;
  if (res && typeof res.data === 'object' && res.status !== 404) {
    if (res.status === 302) {
      dispatch(setError({ status: 302 }));
      return false;
    }
    if (res.status === 429) {
      antd.message.info(
        res && res.data
          ? 'Your API request rate limit has been reached. Please wait a few seconds and try it again.'
          : 'Something Went Wrong.'
      );
    } else if (res.status === 503) {
      Router.push('/error?errorStatus=503');
    } else if (res.data.error.statusCode === 503) {
      Router.push('/error?errorStatus=503');
    } else if (res.data.error.status === 401) {
      dispatch(setError({ status: 401 }));
      return false;
    } else if (res.data.error.status === 403) {
      orgId &&
        (await CommonApi.insufficientPrivilege({ orgId })
          .then((response) => {
            dispatch(
              changePrivilege({ status: true, data: response.data.data })
            );
          })
          .catch((err) => err));
      return res.data;
    } else {
      if (res.data.error.message) {
        dispatch(
          setError({ status: res.status, message: res.data.error.message })
        );
      } else {
        const message = _.values(res.data.error);
        message[0] && message[0][0] && dispatch(setError({ status: res.status, message: message[0][0] }));
      }
      action
        ? dispatch(
            action({
              error: { message: res.data.error.message, status: res.status },
            })
          )
        : '';
      return res.data;
    }
  }
};

