export const getErrorHandle = async (dispatch, action, error) => {
  let msg;
  let status;
  const err = error?.response ? error.response : error;
  status = err && err.status;
  if (status === 302) {
    dispatch(setError({ status, redirect: 'logout' }));
    return false;
  }
  if (status === 503) {
    Router.push('/error?errorStatus=503');
  } else if (status === 404) {
    if (err?.data?.error?.message) msg = err.data.error.message;
    else msg = errorMessageGlobal;
    action
      ? dispatch(action({ status, msg }))
      : dispatch(setError({ status, msg }));
  } else if (status === 401) {
    dispatch(setError({ status, redirect: 'logout' }));
    return false;
  } else if (status === 429) {
    typeof action === 'function' &&
      dispatch(
        action({
          error: {
            message:
              err && err.response
                ? 'Your API request rate limit has been reached. Please wait a few seconds and try it again.'
                : 'Something Went Wrong',
            status,
          },
        })
      );
  } else if (status > 499 && status < 599) {
    typeof action === 'function' &&
      dispatch(action({ error: { message: 'Network problem', status } }));
  } else if (status === 403) {
    dispatch(
      setError({
        status,
        message: 'You are not allowed to perform this action.',
      })
    );
  } else if (status === undefined) {
    if (err?.data?.error) {
      status = err.data.error.status;
      message = err.data.error.message;
      if (status === 401) {
        dispatch(setError({ status, redirect: 'logout' }));
        return false;
      }
      if (status === 404) {
        dispatch(setError({ message, status: 404 }));
        return false;
      }
      if (status > 499 && status < 599) {
        dispatch(setError({ message, status: 503 }));
        return;
      }
      action
        ? dispatch(
            action({
              error: {
                message,
                status,
              },
            })
          )
        : dispatch(
            setError({
              message,
              status,
            })
          );
    }
  }
};

