export const getRecordingStatusBanner =
  (orgId, appId) => (dispatch, getState) => {
    const appID = appId || getState().currentAppReducer['_id'];
    if (orgId && appID) {
      CommonApi.getRecordingStatusBanner(orgId, appID)
        .then((res) => {
          const recordingStatusBanner = { ...getState().recordingStatusBanner };
          recordingStatusBanner.status = true;
          recordingStatusBanner.message = res.data.data.message;
          dispatch(updateRecordingStatusBanner(recordingStatusBanner));
        })
        .catch((error) => error);
    }
  };

