export const fetchPlanHatApi =
  (data) =>
  (...[, getState]) => {
    // if (isLocal) return;
    const loginInFromAdmin = browserCookies.get('loggedInFromAdminDashboard');
    if (!loginInFromAdmin) {
      const profile = { ...getState().profileReducer };
      const currentOrg = { ...getState().currentOrgReducer };
      data.email = profile.email;
      data.companyExternalId = currentOrg?.orgId;
      try {
        planHatApi.createActivity(data);
      } catch (error) {
        console.error('Error sending event to planhat: ', error)
      }
    }
  };

