export const disableEventLimitStatusMessage =
  (data, isFrom) => (dispatch, getState) => {
    CommonApi.disableEventLimitStatusMessage(data)
      .then(async () => {
        const currentState = getState();
        const commonData = currentState.commonReducer;
        const { eventLimitReachStatus } = commonData;
        let item = {};
        if (isFrom === 'isSessionDetails') {
          item = {
            ...eventLimitReachStatus,
            hideEventReachedMessageInSessionDetails:
              !eventLimitReachStatus.hideEventReachedMessageInSessionDetails,
          };
        } else {
          item = {
            ...eventLimitReachStatus,
            hideEventReachedMessage:
              !eventLimitReachStatus.hideEventReachedMessage,
          };
        }
        dispatch(setEventLimitReachedStatus(item));
      })
      .catch((error) => {
        getErrorHandle(dispatch, setEventLimitReachedStatus, error);
      });
  };

