import {axiosInstance} from './globalInstance'

class SessionFilterApi {
  static async fetchRemoteData (data, appId) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/app/${appId}/session-filter/search-attribute`,
      data,
      withCredentials: true
    })
    return response
  }

  static async applyFilter (appId, type, data) {
    const response = await axiosInstance.post(`${process.env.API_URL}/app/${appId}/${type}/custom-list`, data, {withCredentials: true})
    return response
  }

  static async updateOrgChangeEvent (orgId) {
    if(!orgId){
      return undefined
    }
      const response = await axiosInstance({
        method: 'POST',
        url: `${process.env.API_URL}/organization/store-usage-stat`,
        data: {'orgId': orgId, 'eventType': 'visits'},
        withCredentials: true
      })
      return response
    }
}

export default SessionFilterApi
