import { createStore, applyMiddleware, combineReducers } from 'redux';
import { composeWithDevTools } from 'redux-devtools-extension';
import thunkMiddleware from 'redux-thunk';
import {
  applicationReducer,
  currentOrgReducer,
  appTeamReducer,
  selectedSessionReducer,
  sidebarReducer,
  appChecklistReducer,
  selectedUserReducer,
} from 'redux/reducers/applicationReducer';
import { currentAppReducer } from 'redux/reducers/currentAppReducer';
import { csrfReducer } from 'redux/reducers/csrfRuducer';
import { tokenReducer } from 'redux/reducers/tokenReducer';
import { profileReducer } from 'redux/reducers/profileReducer';
import {
  userDetailReducer,
  userAnalyticsReducer,
} from 'redux/reducers/userReducer';
import { appChangeReducer } from 'redux/reducers/appChangeReducer';
import {
  screenReducer,
  screenDetailReducer,
  screenRenamedList,
} from 'redux/reducers/screenReducer';
import {
  urlReducer,
  privilegeReducer,
  recordingStatusBanner,
  orgAppReducer,
  commonReducer,
} from 'redux/reducers/commonReducer';
import { errorReducer } from 'redux/reducers/errorReducer';
import {
  currentSubscriptionReducer,
  orgAvailablePlanReducer,
  orgAppTeamListReducer,
  invoiceReceiptReducer,
  sessionUsageReducer,
} from 'redux/reducers/subscriptionReducer';

import { organizationReducer } from 'redux/reducers/organizationReducer';
import { overviewReducer } from 'redux/reducers/overviewUsageStatisticsReducer';
import {
  userFilterList,
  userFilterProperties,
  showUserFilterMenu,
} from 'redux/reducers/userFilterReducer';
import { accessManagementReducer } from 'redux/reducers/accessManagementReducer';
import { megaFilterReducer } from 'redux/reducers/megaFilterReducer';
import screenTimelineReducer from 'redux/reducers/screenTimelineReducer';
import { statisticsReducer } from 'redux/reducers/statisticsReducer';
import { sessionStatisticsReducer } from 'redux/reducers/sessionStatisticsReducer';
import { appFilter } from 'redux/reducers/appFilterReducer';
import { eventTable } from 'redux/reducers/eventReducer';
import { authReducer } from 'redux/reducers/authReducer';
import { quoteReducer } from 'redux/reducers/quoteReducer';
import { isProd } from 'Utils/constants/variables';
import ssoReducer from 'redux/reducers/ssoreducer';

const rootReducer = combineReducers({
  auth: authReducer,
  applicationReducer,
  currentOrgReducer,
  organizationApp: orgAppReducer,
  currentAppReducer,
  recordingStatusBanner,
  urlReducer,
  commonReducer,
  tokenReducer,
  csrfReducer,
  profileReducer,
  userDetailReducer,
  appChangeReducer,
  screenReducer,
  screenDetailReducer,
  errorReducer,
  privilegeReducer,
  currentSubscriptionReducer,
  sessionUsageReducer,
  orgAvailablePlanReducer,
  orgAppTeamListReducer,
  organizationReducer,
  appTeamReducer,
  selectedSessionReducer,
  invoiceReceiptReducer,
  userFilterList,
  userFilterProperties,
  showUserFilterMenu,
  overviewReducer,
  sidebarReducer,
  statisticsReducer,
  eventTable,
  sessionStatisticsReducer,
  quoteReducer,
  screenRenamedList,
  appChecklistReducer,
  selectedUserReducer,
  ssoInfo: ssoReducer,
  accessManagement: accessManagementReducer,
  screenTimelineReducer,
  appFilter,
  megaFilterReducer,
  userAnalyticsReducer,
});
const composeEnhancers = composeWithDevTools({
  trace: true,
  traceLimit: 25,
});
const initStore = (initState = {}) =>
  createStore(
    rootReducer,
    initState,
    !isProd
      ? composeEnhancers(applyMiddleware(thunkMiddleware))
      : applyMiddleware(thunkMiddleware)
  );
export default initStore;
