
import { currentTimeZone } from 'Utils/DateConversion/dateConversionUtils'
import {
  SESSION_STATISTICS,
  SESSION_STATISTICS_GRAPH,
  LOG_OUT,
  SESSION_STATISTICS_DLIST,
  SESSION_STATISTICS_BOXES,
  SESSION_STATISTICS_BOXES_UNIQ_TOP,
} from '../../types'

const initialState = {
  group_list: [
    {
      table: 'session',
      attribute: 'session_period',
      tooltip: 'Day on which session was recorded.',
      period: 86400,
      display: 'day',
      time_zone_offset: currentTimeZone,
    },
  ],
  aggregation_list: {
    table: 'session',
    attribute: 'session_count',
    operator: '',
  },
  series_plot_options: {},
  selectedBox: {
    attrOfSmallBox: 'count',
    mainKey: 'Sessions',
    tooltip: 'Total number of recorded app launches.',
    graph_info: 'Recorded session number',
    actionIndex: 1
  },
  selectedTab: 'sessionsList',
}
export const sessionStatisticsReducer = (state = initialState, action) => {
  switch (action.type) {
    case SESSION_STATISTICS:
      return action.data ? action.data : state
    case SESSION_STATISTICS_GRAPH:
      return {
        ...state,
        graphData: action.data.graphData,
      }
    case SESSION_STATISTICS_DLIST:
      return {
        ...state,
        groupingOptions: action.data,
      }
    case SESSION_STATISTICS_BOXES:
      return {
        ...state,
        statsBoxes: action.data.statsBoxes,
      }
    case SESSION_STATISTICS_BOXES_UNIQ_TOP:
      return {
        ...state,
        uniqueUserBox: action.data.uniqueUserBox,
      }
    case LOG_OUT:
      return {}
    default:
      return state
  }
}
