import { LOG_OUT, EVENT_NAME } from '../../types'

export const eventTable = (
  state = {
    selectedEvent: [],
    manuallyChanged: false,
  },
  action
) => {
  switch (action.type) {
    case EVENT_NAME:
      return action.data === undefined ? state : action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}
