import {
  CURRENT_URL,
  LOG_OUT,
  VIDEO_TABLE,
  VJS_CUSTOM,
  INSUFFICIENT_PRIVILEGE,
  SCREEN_REQUEST,
  USER_REQUEST,
  SESSION_REQUEST,
  RECORDING_STATUS_BANNER,
  DASHBOARD_TABLE,
  ORGANIZATION_APP_DATA,
  ANY_PAGE_DATA,
  SESSION_PROCESSING_INFO,
  API_CALLED_TIME,
  API_CALLED_TIME_EXTRA,
  EVENT_LIMIT_REACHED_STATUS,
  GET_EVENT_PROPERTY_LIST,
} from '../../types'

export const urlReducer = (state = { url: null }, action) => {
  switch (action.type) {
    case CURRENT_URL:
      return action.data
    // case LOG_OUT:
    //     return [];
    default:
      return state
  }
}


export const privilegeReducer = (state = {}, action) => {
  switch (action.type) {
    case INSUFFICIENT_PRIVILEGE:
      return action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const recordingStatusBanner = (
  state = { status: true, message: null },
  action
) => {
  switch (action.type) {
    case RECORDING_STATUS_BANNER:
      return action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const orgAppReducer = (state = {}, action) => {
  switch (action.type) {
    case ORGANIZATION_APP_DATA:
      return action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const commonReducer = (
  state = {
    eventPropertyList: []
  },
  action
) => {
  switch (action.type) {
    case ANY_PAGE_DATA:
      return action.data
    case SESSION_PROCESSING_INFO:
      return {
        ...state,
        sessionProcessingInfo: action.data.sessionProcessingInfo,
      }
    case API_CALLED_TIME:
      return {
        ...state,
        apiCalledTime: action.apiCalledTime,
      }
    case API_CALLED_TIME_EXTRA:
      return {
        ...state,
        apiCalledTimeExtra: action.apiCalledTimeExtra,
      }
    case EVENT_LIMIT_REACHED_STATUS:
      return {
        ...state,
        eventLimitReachStatus: action.eventLimitReachStatus
      }
    case GET_EVENT_PROPERTY_LIST:
    return {
      ...state,
      eventPropertyList: action.eventPropertyList
    }
    case LOG_OUT:
      return []
    default:
      return state
  }
}
