import { useIsAppType } from "hooks/useIsAppType";
import React, { createContext, useContext, useMemo, useState } from "react";
import { useSelector } from "react-redux";
import { IPagination } from "types/common";
import { INocodeEvent } from "types/nocodeEvents";
import { IReduxState } from "types/reduxStateTypes";
import { IAction, ISessionScreen } from "types/sessionTypes";

interface IProps {
	children: React.ReactNode
}

interface INoCodeEventsContextProps {
	noCodeEventsFeatureFlag?: boolean
	managePopupOpen: boolean
	setManagePopupOpen: ( state: boolean ) => void
	deletePopupOpen: boolean
	setDeletePopupOpen: ( state: boolean ) => void
	currentAction?: IAction,
	setCurrentAction: ( action: IAction | undefined ) => void,  
	currentScreen?: ISessionScreen,
	setCurrentScreen: ( event: ISessionScreen | undefined ) => void,
	events?: INocodeEvent[],
	setManageListPagination: ( pagination: IPagination ) => void,
	manageListPagination?: IPagination,
	setEvents: ( event: INocodeEvent[] ) => void,
	setManageListPage: ( page: number ) => void,
	manageListPage: number | undefined,
	screenEventModalOpen: boolean
	setScreenEventModalOpen: ( state: boolean ) => void
	duplicateEventModalOpen: boolean
	setDuplicateEventModalOpen: ( state: boolean ) => void
	deleteScreenEventPopupOpen: boolean
	setDeleteScreenEventPopupOpen: ( state: boolean ) => void,
	showDashboardTemplate: boolean,
	setShowDashboardTemplate: (state: boolean) => void,
	showNoCodeEventsTutorial: boolean,
	setShowNoCodeEventsTutorial: ( state: boolean ) => void
}

const NoCodeEventsContext = createContext<INoCodeEventsContextProps>( {
	noCodeEventsFeatureFlag: false,
	managePopupOpen: false,
	setManagePopupOpen: () => null,
	deletePopupOpen: false,
	setDeletePopupOpen: () => null,
	currentAction: undefined,
	setCurrentAction: () => null,
	currentScreen: undefined,
	setCurrentScreen: () => null,
	events: undefined,
	setEvents: () => null,
	setManageListPagination: () => null,
	manageListPagination: undefined,
	setManageListPage: () => null,
	manageListPage: undefined,
	screenEventModalOpen: false,
	setScreenEventModalOpen: () => null,
	duplicateEventModalOpen: false,
	setDuplicateEventModalOpen: () => null,
	deleteScreenEventPopupOpen: false,
	setDeleteScreenEventPopupOpen: () => null,
	showDashboardTemplate: false,
	setShowDashboardTemplate: () => null,
	showNoCodeEventsTutorial: false,
	setShowNoCodeEventsTutorial: () => null
} )

const NoCodeEventsContextProvider: React.FC<IProps> = ( { children } ) => {
	const [ managePopupOpen, setManagePopupOpen ] = useState( false )
	const [ deletePopupOpen, setDeletePopupOpen ] = useState( false )
	const [ screenEventModalOpen, setScreenEventModalOpen ] = useState( false )
	const [ duplicateEventModalOpen, setDuplicateEventModalOpen ] = useState( false )
	const [ deleteScreenEventPopupOpen, setDeleteScreenEventPopupOpen ] = useState( false )
	const [ currentAction, setCurrentAction ] = useState<IAction | undefined>( undefined )
	const [ currentScreen, setCurrentScreen ] = useState<ISessionScreen | undefined>( undefined )
	const [ manageListPagination, setManageListPagination ] = useState<IPagination>()
	const [ manageListPage, setManageListPage ] = useState<number | undefined>( undefined )
	const [ events, setEvents ] = useState<INocodeEvent[]>()
	const [showDashboardTemplate, setShowDashboardTemplate] = useState<boolean>(false)
	const [ showNoCodeEventsTutorial, setShowNoCodeEventsTutorial ] = useState( false )
    const { currentOrgReducer: currentOrg } = useSelector((state: IReduxState) => state);
    const isWebApp = useIsAppType('web');

	const noCodeEventsFeatureFlag = ( currentOrg.planFeature?.smartEvent && !isWebApp ) || false

	const value = useMemo( () => ( {
		noCodeEventsFeatureFlag,
		managePopupOpen,
		setManagePopupOpen,
		deletePopupOpen,
		setDeletePopupOpen,
		currentAction,
		setCurrentAction,
		currentScreen,
		setCurrentScreen,
		events,
		setEvents,
		setManageListPagination,
		manageListPagination,
		setManageListPage,
		manageListPage,
		screenEventModalOpen,
		setScreenEventModalOpen,
		deleteScreenEventPopupOpen,
		setDeleteScreenEventPopupOpen,
		showNoCodeEventsTutorial,
		setShowNoCodeEventsTutorial,
		showDashboardTemplate,
		setShowDashboardTemplate,
		duplicateEventModalOpen,
		setDuplicateEventModalOpen
	} ), [ 
		noCodeEventsFeatureFlag,
		managePopupOpen,
		setManagePopupOpen,
		deletePopupOpen,
		setDeletePopupOpen,
		currentAction,
		setCurrentAction,
		currentScreen,
		setCurrentScreen,
		events,
		setEvents,
		setManageListPagination,
		manageListPagination,
		setManageListPage,
		manageListPage,
		screenEventModalOpen,
		setScreenEventModalOpen,
		deleteScreenEventPopupOpen,
		setDeleteScreenEventPopupOpen,
		showNoCodeEventsTutorial,
		showDashboardTemplate,
		setShowDashboardTemplate,
		duplicateEventModalOpen,
	] )

	return (
		<NoCodeEventsContext.Provider value={ value }>
			{ children }
		</NoCodeEventsContext.Provider>
	)
}

const useNoCodeEventsContext = () => useContext( NoCodeEventsContext )

export {
	useNoCodeEventsContext,
	NoCodeEventsContextProvider
}