import { ACCESS_CHECK_PLAN_STATUS, ACCESS_APP_LIST, ACCESS_USER_LIST,  LOG_OUT } from '../../types'

export const accessManagementReducer = (state = {}, action) => {
  switch (action.type) {
    case ACCESS_CHECK_PLAN_STATUS:
      return {
        ...state,
        planStatus: action.data,
      }
    case ACCESS_APP_LIST:
      return {
        ...state,
        appList: action.data,
      }
    case ACCESS_USER_LIST:
      return {
        ...state,
        userList: action.data,
      }
    case LOG_OUT:
      return {}
    default:
      return state
  }
}
