import '../Utils/suppressLayoutEffectWarning';
import React, { useEffect, useState } from 'react';
import withRedux from 'next-redux-wrapper'
import { Provider } from 'react-redux'
// import { useRouteChangeTrace } from 'hooks/useRouteChangeTrace';
import { changeUrl, cookies } from 'redux/actions/common'
import 'antd/dist/antd.css';
import 'swiper/css/swiper.min.css';
import 'styles/onboard_form.scss'
import 'styles/dashboard.scss'
import 'styles/table.scss'
import { NoCodeEventsContextProvider } from 'components/features/sessions/Context/NoCodeEventsContext'
import textToCheck from 'Utils/helpers/textToCheck';
import validateEmail from 'Utils/helpers/validateEmail';
import type { AppProps as AppPropsDefaults } from 'next/app';
import type LayoutType from 'components/IntegratePages/layout';
import ErrorBoundary from 'components/common/ErrorBoundary'
import { FeatureFlagsContextProvider } from 'components/common/Contexts/FeatureFlagsContext';
import Script from 'next/script';
import initStore from '../redux/store'

interface AppComponent extends React.FC<any> {
  layout?: typeof LayoutType,
  getInitialProps: ( context: any ) => Promise<any>
}

interface AppProps extends AppPropsDefaults {
  store: any;
  pageLevelError: any;
  query: any;
  ctx: any;
  Component: AppComponent;
  getInitialProps: ( context: AppProps ) => Promise<any>
}

interface IApp<T> extends React.FC<T> {
  getInitialProps: ( context: T ) => Promise<any>
}

const App: IApp<AppProps> = ( props ) => {
  const { Component, pageProps, store, router: cxtRouteProps, pageLevelError } = props
  const [isValidRedirectUrl, setIsValidRedirectUrl] = useState(false)
  const {errorReducer} = store.getState()
  // useRouteChangeTrace() // use for tracing the route change
  useEffect(() => {
    const routerProps = { ...cxtRouteProps }
    const { query } = ( routerProps as any )?.state as any
    const redirectProps = query?.redirect
    let isValidRedirectUrlD
    if (redirectProps) {
      if (redirectProps.startsWith('/') && !validateEmail(redirectProps)) {
        setIsValidRedirectUrl(true)
      } else {
        isValidRedirectUrlD = textToCheck(redirectProps)
        const type = isValidRedirectUrlD[0]?.text
          ? isValidRedirectUrlD[0]?.type
          : isValidRedirectUrlD[1]?.type
        if (type === 'link' && !validateEmail(redirectProps)) {
          setIsValidRedirectUrl(true)
        } else setIsValidRedirectUrl(false)
      }
    }
  }, [])

  useEffect(() => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker
        .register('/service-worker.js')
    }
  }, []);

    // Unregister all Service Workers
    // useEffect(() => {
    //     if ('serviceWorker' in navigator) {
    //     navigator.serviceWorker.getRegistrations().then((registrations) => {
    //         registrations.forEach((registration) => {
    //         registration.unregister().then(() => {
    //             console.log('Service Worker unregistered:', registration);
    //         }).catch((error) => {
    //             console.error('Service Worker unregistration failed:', error);
    //         });
    //         });
    //     }).catch((error) => {
    //         console.error('Error retrieving Service Worker registrations:', error);
    //     });
    //     }
    // }, []);
  // eslint-disable-next-line react/jsx-no-useless-fragment
  const Layout = Component.layout || (({ children }) => <>{children}</>)
  return (
    <Provider store={store}>
      <Script type="text/javascript"
        defer
        id="web-sdk-loader"
        // eslint-disable-next-line react/no-danger
        dangerouslySetInnerHTML={ {
          __html: `
          (function( appKey, opts ) {
            window.uxc = {
              __t: [],
              __ak: appKey,
              __o: opts,
              event: function( n, p ) {
                this.__t.push( [ 'event', n, p ] )
              },
              setUserIdentity: function( i ) {
                this.__t.push( [ 'setUserIdentity', i ] )
              },
              setUserProperty: function( k, v ) {
                this.__t.push( [ 'setUserProperty', k, v ] )
              },
              setUserProperties: function( p ) {
                this.__t.push( [ 'setUserProperties', p ] )
              },
              abort: function() {
                this.__t.push( [ 'abort' ] )
              }
            };
            var head = document.getElementsByTagName('head')[0];
            var script = document.createElement('script');
            script.type = 'text/javascript';
            script.src = '//websdk-recording.uxcam.com/index.js';
            script.async = true;
            script.defer = true;
            script.id = 'uxcam-web-sdk';
            script.crossOrigin = 'anonymous';
            head.appendChild(script);
          } )( '${process.env.UXCAM_WEBSDK_APP_KEY}', {
            appVersion: '1.0.0',
            occlusion: {
              queryParams: [
                'redirect',
              ],
            },
          } );
          `
        } }
      />
      <ErrorBoundary errorReducer={errorReducer} pageLevelError={pageLevelError}>
        <FeatureFlagsContextProvider>
          <NoCodeEventsContextProvider>
            <Layout
              query={cxtRouteProps?.query}
            >
              <Component {...pageProps} isValidRedirectUrl={isValidRedirectUrl} />
            </Layout>
          </NoCodeEventsContextProvider>
        </FeatureFlagsContextProvider>
      </ErrorBoundary>
    </Provider>
  )
}
App.getInitialProps = async ({ Component, ctx }: AppProps) => {
  const { res, req, store, query, err } = ctx
  if (query) {
    if (query.url === '/dashboard') query.parentType = 'dashboard'
    if (query.url === '/login') query.parentType = 'login'
    query.url = ctx.asPath
    ctx.store.dispatch(changeUrl(query))
  }
  let getCookies
  let pageProps = {}
  if (res) {
    res.setHeader('Link', '<https://static-build.uxcam.com/>; rel=preconnect; crossorigin')
    if (req?.cookies?.token) {
      getCookies = encodeURIComponent(req.cookies.token)
    } else {
      getCookies = ''
    }
    store.dispatch(cookies(getCookies))
  }
  pageProps =
    Component.getInitialProps && (await Component.getInitialProps(ctx))
  return req
    ? {
        pageProps: {
          ...pageProps,
          appid: ctx?.query?.appId,
          pageLevelError: err,
        },
      }
    : { pageProps: { ...pageProps } }
}
export default withRedux(initStore)(App)
