import {
  OVERVIEW_USAGE_STATS,
  ACTIVE_USER_BOX,
  TOTAL_ENGAGEMENT_BOX,
  RAGE_TAP_TIME_BOX,
  TOP_EVENT_BOX,
  TOP_APPVERSION_BOX,
  AVERAGE_SESSION_LENGTH_BOX,
  TOP_COUNTRY_BOX,
  TOP_SCREEN_BOX,
  TOP_DEVICESIZE_BOX,
  TOP_WEEK_TIME_BOX,
  UX_GRAPH_DATA,
  USAGE_GRAPH_DATA,
  LOADER_USAGE_STATS,
  LOADER_UX_STATS,
  LOG_OUT,
  OVERVIEW_FETCHED_APP_ID,
  TOP_CITY_BOX,
  TOP_DEVICE_BOX,
} from '../../types';

export const overviewReducer = (
  state = {
    graph_name: 'total_engagement_graph',
    uxGraphName: 'top_week_time_graph',
    period: 'week',
    loader: false,
    UXloader: false,
    fetchedAppId: '',
  },
  action
) => {
  switch (action.type) {
    case OVERVIEW_USAGE_STATS:
      return action.data === undefined ? state : action.data;
    case ACTIVE_USER_BOX:
      return {
        ...state,
        active_user_box: action.data.active_user_box
      };
    case TOP_CITY_BOX: {
      return {
        ...state,
        top_city_box: action.data.top_city_box,
      }
    }
    case TOP_DEVICE_BOX: {
      return {
        ...state,
        top_device_box: action.data.top_device_box,
      }
    }
    case TOTAL_ENGAGEMENT_BOX:
      return {
        ...state,
        total_engagement_box: action.data.total_engagement_box
      };
    case RAGE_TAP_TIME_BOX:
      return {
        ...state,
        rage_tap_time_box: action.data.rage_tap_time_box
      };
    case TOP_EVENT_BOX:
      return {
        ...state,
        top_event_box: action.data.top_event_box
      };
    case TOP_APPVERSION_BOX:
      return {
        ...state,
        top_appversion_box: action.data.top_appversion_box
      };
    case AVERAGE_SESSION_LENGTH_BOX:
      return {
        ...state,
        average_session_length_box: action.data.average_session_length_box
      };
    case TOP_COUNTRY_BOX:
      return {
        ...state,
        top_country_box: action.data.top_country_box
      };
    case TOP_SCREEN_BOX:
      return {
        ...state,
        top_screen_box: action.data.top_screen_box
      };
    case TOP_DEVICESIZE_BOX:
      return {
        ...state,
        top_devicesize_box: action.data.top_devicesize_box
      };
    case TOP_WEEK_TIME_BOX:
      return {
        ...state,
        top_week_time_box: action.data.top_week_time_box
      };
    case USAGE_GRAPH_DATA:
      return {
        ...state,
        graphDataByUsage: action.data.graphDataByUsage
      };
    case UX_GRAPH_DATA:
      return {
        ...state,
        graphDataByUX: action.data.graphDataByUX
      };
    case LOADER_USAGE_STATS:
      return {
        ...state,
        loader:
          action.data.loader === undefined ? state.loader : action.data.loader
      };
    case LOADER_UX_STATS:
      return {
        ...state,
        UXloader:
          action.data.UXloader === undefined
            ? state.UXloader
            : action.data.UXloader
      };
    case OVERVIEW_FETCHED_APP_ID:
      return {
        ...state,
        fetchedAppId: action.data
      };
    case LOG_OUT:
      return [];
    default:
      return state;
  }
};
export default overviewReducer;
