import {
  APPLICATION_LIST,
  CURRENT_ORGANIZATION,
  APP_TEAM,
  LOG_OUT,
  ADD_SESSION_ID,
  SIDEBAR_COLLAPSE,
  APP_CHECKLIST,
  ADD_USER_ID,
  SETTING_TAB,
} from '../../types';

export const applicationReducer = (state = null, action) => {
  switch (action.type) {
    case APPLICATION_LIST:
      return action.data === undefined ? state : action.data;
    case LOG_OUT:
      return [];
    default:
      return state;
  }
};

