module.exports = function (textToCheck) {
  const expression = /(https?:\/\/)?[\w\-~]+(\.[\w\-~]+)+(\/[\w\-~@:%]*)*(#[\w\-]*)?(\?[^\s]*)?/gi
  const topDomains = [
    /\.com/,
    /\.de/,
    /\.org/,
    /\.net/,
    /\.us/,
    /\.co/,
    /\.edu/,
    /\.gov/,
    /\.biz/,
    /\.za/,
    /\.info/,
    /\.cc/,
    /\.ca/,
    /\.cn/,
    /\.fr/,
    /\.ch/,
    /\.au/,
    /\.in/,
    /\.jp/,
    /\.be/,
    /\.it/,
    /\.nl/,
    /\.uk/,
    /\.mx/,
    /\.no/,
    /\.ru/,
    /\.br/,
    /\.se/,
    /\.es/,
    /\.at/,
    /\.dk/,
    /\.eu/,
    /\.il/,
  ]
  const regex = new RegExp(expression)
  let match = ''
  const splitText = []
  let startIndex = 0
  let domainMatch = ''
  let urlLength = 0
  let abort = false
  while ((match = regex.exec(textToCheck)) !== null) {
    abort = true
    for (let i = 0; i < topDomains.length; i++) {
      domainMatch = match[0].match(topDomains[i])
      if (domainMatch) {
        urlLength = domainMatch[0].length + domainMatch.index
        if (match[0].length === urlLength) abort = false
        if (match[0].length > urlLength) {
          if (match[0].substr(urlLength, 1) === '/') abort = false
        }
      }
    }
    if (match.index !== 0 && textToCheck[match.index - 1] === '@') {
      abort = true
    }

    if (
      match.index !== 0 &&
      textToCheck[match.index + match[0].length - 1] === '?'
    ) {
      match[0] = match[0].substr(0, match[0].length - 1)
    }
    splitText.push({
      text: textToCheck.substr(startIndex, match.index - startIndex),
      type: 'text',
    })
    if (abort) {
      splitText.push({
        text: textToCheck.substr(match.index, match[0].length),
        type: 'text',
      })
    } else {
      let cleanedLink = textToCheck.substr(match.index, match[0].length)
      cleanedLink = cleanedLink.replace(/^https?:\/\//, '')
      splitText.push({ text: cleanedLink, type: 'link' })
    }
    startIndex = match.index + match[0].length
  }
  if (startIndex < textToCheck.length)
    splitText.push({ text: textToCheck.substr(startIndex), type: 'text' })

  return splitText
}
