import fetch from 'isomorphic-unfetch';
import axios from 'axios';
import userApi from './userApi';
import { axiosInstance } from './globalInstance';

const { CancelToken } = axios;
let cancel = null;
let detailCancel = null;
let request = 0;
let eventCancel = null;
let gestureCancel = null;
let bugDetailCancel = null;
let screenListCancel = null;
let aiSessionsListCancel = null;
let aiUserSessionsCancel = null;
class SessionTableApi {
  static async getSession(appId) {
    request++;
    if (cancel) {
      await cancel(request);
    }
    const response = await axiosInstance.get(
      `${process.env.API_URL}/app/${appId}/session`,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
    cancel = null;
    return response;
  }

  static async getV2SessionsList(data) {
    request++;
    if (cancel) await cancel(request);
    const response = await axiosInstance.post(
      `${process.env.PYTHON_API_URL_V2}/sessions/list`,
      data,
      {
        withCredentials: true,
        credentials: 'include',
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
    cancel = null;
    return response;
  }

  static async getV2AISessionsList(data) {
    request++;
    if (aiSessionsListCancel) await aiSessionsListCancel();
    const response = await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/ai/sessions/list`,
      data,
      {
        withCredentials: true,
        credentials: 'include',
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          aiSessionsListCancel = c;
          request = 0;
        }),
      }
    );
    aiSessionsListCancel = null;
    return response;
  }
    
  static async getV2AIUserSessions(data) {
    request++;
    if (aiUserSessionsCancel) await aiUserSessionsCancel(request);
    const response = await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/ai/sessions/user_sessions`,
      data,
      {
        withCredentials: true,
        credentials: 'include',
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          aiUserSessionsCancel = c;
          request = 0;
        }),
      }
    );
    aiUserSessionsCancel = null;
    return response;
  }
  
  static async sortColumn(data, cookies, appId, type, userId, screenName) {
    const updatedData = {
      ...data,
      appid: appId
    }
    await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/preference/column-sort-order`,
      updatedData,
      { withCredentials: true }
    );
    if (data.table === 'sessionTable' && data.filter) {
      const res = await this.getPageData(data, cookies, appId, type);
      return { data: { data: res } };
    }
    if (type === 'session') {
      if (userId && data.table === 'smallUserSessionTable') {
        return userApi.getUserSmallTable(
          appId,
          data.filter,
          data.page,
          data.dateRange
        );
      }
      if (screenName) {
        return this.getScreenSession(
          appId,
          cookies,
          screenName,
          data.filter,
          data.page,
          data.dateRange
        );
      }
      return this.getSession(appId, cookies);
    }
    if (type === 'user' || type === 'screen' || type === 'event') {
      const res = await this.getPageData(data, cookies, appId, type);
      return { data: { data: res } };
    }
  }

  static async getUserSession(appId, cookies, userId) {
    const sentCookies = `token=${cookies}`;
    const csrfResponse = await fetch(`${process.env.API_URL}/app/csrf`, {
      credentials: 'include',
      headers: { Cookie: sentCookies },
    });
    const csrfres = await csrfResponse.json();
    const _csrf = csrfres.data.csrf.token;

    const sessionres = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/app/${appId}/session/custom-list`,
      data: {
        page: 1,
        uxcamuserid: userId,
        _csrf,
        table: 'smallUserSessionTable',
      },
      withCredentials: true,
    });
    return sessionres;
  }

  static async getScreenSession(
    appId,
    cookies,
    screenName,
    filter,
    page,
    dateRange,
    orderBy
  ) {
    const sentCookies = `token=${cookies}`;
    const csrfResponse = await fetch(`${process.env.API_URL}/app/csrf`, {
      credentials: 'include',
      headers: { Cookie: sentCookies },
    });
    const csrfres = await csrfResponse.json();
    const _csrf = csrfres.data.csrf.token;

    const sessionres = await axiosInstance({
      method: 'POST',
      // url:  process.env.API_URL+`/app/${appId}/session/custom-list`,
      url: `${process.env.API_URL}/app/${appId}/screen/sessions`,
      data: { page: page || 1, filter, _csrf, dateRange, orderBy },
      withCredentials: true,
    });
    return sessionres;
  }

  static async getPageData(data, _, appId, type) {
    request++;
    if (cancel) {
      await cancel(request);
    }
    const response = await axiosInstance.post(
      `${process.env.API_URL}/app/${appId}/${type}/custom-list`,
      data,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
    cancel = null;
    return response.data.data;
  }

  static async getSessionFilter(appId) {
    const response = await axiosInstance({
      method: 'Get',
      url: `${process.env.API_URL}/app/${appId}/session-filter`,
      withCredentials: true,
    });

    return response;
  }

  static async createSessionFilter(appId) {
    const response = await axiosInstance({
      method: 'Get',
      url: `${process.env.API_URL}/app/${appId}/session-filter/create`,
      withCredentials: true,
    });
    return response;
  }

  static async fetchRemoteData(data, appId) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/app/${appId}/session-filter/search-attribute`,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async addWatchedSession(data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/label/session/update_custom_label`,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async addMetaDataForVideo(data, appId) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${
        process.env.REDIRECT_URL === 'https://appuat.uxcam.com'
          ? process.env.PYTHON_API_URL
          : process.env.API_URL
      }${
        process.env.REDIRECT_URL !== 'https://appuat.uxcam.com'
          ? '/forward'
          : ''
      }/forward${
        process.env.REDIRECT_URL === 'https://appuat.uxcam.com' ? '/' : ''
      }`,
      data: { name: 'add_metadata_s3_video', kwargs: data, appid: appId },
      withCredentials: true,
    });
    return response;
  }

  static async getCrashLog(appId, sessionId, shareSessionKey) {
    const urlkey = shareSessionKey ? '/share/app/' : '/app/';
    const response = await axiosInstance({
      method: 'Get',
      url: `${
        process.env.API_URL + urlkey + appId
      }/session/${sessionId}/crash-file-download`,
      withCredentials: true,
    });
    return response;
  }

  static async getCrashSession(data, type) {
    const urlKey = data.shareKey
      ? `/crashes/public/crash_logs`
      : `/crashes/crash_logs`;
    const response = await axiosInstance({
      method: 'POST',
      url: process.env.PYTHON_API_URL + urlKey,
      data: delete data.shareKey && data,
      withCredentials: true,
    });
    return response;
  }

  static async getAnrSessionDetail(data, type) {
    const urlKey = data.shareKey
      ? `/uifreezes/public/ui_freeze_logs`
      : `/uifreezes/ui_freeze_logs`;
    const response = await axiosInstance({
      method: 'POST',
      url: process.env.PYTHON_API_URL + urlKey,
      data: delete data.shareKey && data,
      withCredentials: true,
    });
    return response;
  }

    // implemented on issue detail page

  static async sortListPageColumn(data) {
    await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/preference/column-sort-order`,
      data,
      { withCredentials: true }
    );
  }

  static async getBugSession(data, urlKey) {
    const response = await axiosInstance({
      method: 'POST',
      url: process.env.PYTHON_API_URL + urlKey,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async addSessionNote(data) {
    const url = `${process.env.PYTHON_API_URL}/notes/session/create`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      data,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }

  static async fetchSessionNote(data) {
    const url = `${process.env.PYTHON_API_URL}/notes/session/list`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async updateSessionNote(data) {
    const url = `${process.env.PYTHON_API_URL}/notes/session/edit`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      withCredentials: true,
      data,
    });
    return response;
  }

  static async deleteSessionNote(data) {
    const url = `${process.env.PYTHON_API_URL}/notes/session/delete/${data.appid}/${data.note_id}`;
    return axiosInstance({
      method: 'DELETE',
      url,
      withCredentials: true,
    });
  }

  static async fetchMentionUserList(appId) {
    const response = await axiosInstance({
      method: 'Get',
      url: `${process.env.PYTHON_API_URL}/app/team/${appId}`,
      withCredentials: true,
    });
    return response;
  }

  static async fetchEventsForScreenTimeLine(data) {
    request++;
    if (eventCancel) {
      await eventCancel(request);
    }
    const url = `${process.env.PYTHON_API_URL_V2}/sessions/get-event-details`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      withCredentials: true,
      data,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        eventCancel = c;
        request = 0;
      }),
    });
    eventCancel = null;
    return response;
  }

  static async fetchBugInfoSessionDetail(data) {
    request++;
    if (bugDetailCancel) {
      await bugDetailCancel(request);
    }
    const url = `${process.env.PYTHON_API_URL_V2}/sessions/get-bug-details`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      withCredentials: true,
      data,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        bugDetailCancel = c;
        request = 0;
      }),
    });
    bugDetailCancel = null;
    return response;
  }

  static async fetchScreenNames(data) {
    request++;
    if (screenListCancel) {
      await screenListCancel(request);
    }
    const url = `${process.env.PYTHON_API_URL_V2}/sessions/get-all-screens`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      withCredentials: true,
      data,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        screenListCancel = c;
        request = 0;
      }),
    });
    screenListCancel = null;
    return response;
  }

  static async fetchSessionEventDetails( sessionId, appId ) {
    const { data: { data } } = await axiosInstance( {
      method: "POST",
      url: `${process.env.PYTHON_API_URL_V2}/sessions/get-event-details`,
      withCredentials: true,
      data: {
        sessionid: sessionId,
        appid: appId,
      }
    } )
    return data
  }

  static async fetchSessionBugDetails( sessionId, appId ) {
    const { data: { data } } = await axiosInstance( {
      method: "POST",
      url: `${process.env.PYTHON_API_URL_V2}/sessions/get-bug-details`,
      withCredentials: true,
      data: {
        sessionid: sessionId,
        appid: appId,
      }
    } )
    return data
  }

  static async fetchSessionScreenNames( payload ) {
    const data = await axiosInstance( {
      method: "POST",
      url: `${process.env.PYTHON_API_URL_V2}/sessions/get-all-screens`,
      withCredentials: true,
      data: payload
    } )
    return data;
  }

  static async fetchSessionListV2( data ) {
    const response = await axiosInstance( {
      method: "POST",
      url: `${process.env.PYTHON_API_URL_V2}/sessions/list`,
      withCredentials: true,
      data
    } )
    return response
  }
}

export default SessionTableApi;
