import {CURRENT_SUBSCRIPTION,
  QUERY_PLAN_CHANGE,
  PAYMENT_HISTORY_TABLE,
  ORG_AVAILABLE_PLANS,
  ORG_APP_TEAM_LIST,
  INVOICE_RECEIPT,
  SESSION_USAGE,
  WEB_SESSION_USAGE,
  LOG_OUT} from '../../types'

export const currentSubscriptionReducer = (state = {}, action) => {
  switch (action.type) {
    case CURRENT_SUBSCRIPTION:
      return action.data ? action.data : null
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const orgAvailablePlanReducer = (state = {}, action) => {
  switch (action.type) {
    case ORG_AVAILABLE_PLANS:
      return action.data ? action.data : null
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const orgAppTeamListReducer = (state = {apps: [], team: []}, action) => {
  switch (action.type) {
    case ORG_APP_TEAM_LIST:
      return action.data ? action.data : {apps: [], team: []}
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const invoiceReceiptReducer = (state = {customer: {}, transaction: {}}, action) => {
  switch (action.type) {
    case INVOICE_RECEIPT:
      return action.data ? action.data : {customer: {}, transaction: {}}
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const sessionUsageReducer = (state = {}, action) => {
  switch (action.type) {
    case SESSION_USAGE:
    case WEB_SESSION_USAGE:
      return action.data ? { ...state, ...action.data } : null
    case LOG_OUT:
      return []
    default:
      return state
  }
}

