import React, { useMemo } from 'react'
import { useSessionTimeLine } from "components/shared/Sessions/Context"
import { useSelector } from "react-redux"
import { IReduxState } from "types/reduxStateTypes"
import { ISessionTimeline } from "types/sessionTypes"
import { FeatureFlagsProvider } from "uxcam-frontend-components"
import Cookies from 'universal-cookie';

export const FeatureFlagsContextProvider: React.FC<{
	children: React.ReactNode;
}> = ( { children } ) => {

	const {
		currentOrgReducer,
		currentAppReducer
	} = useSelector( ( state: IReduxState ) => state )
	const { sessionDetail } = useSessionTimeLine() as unknown as ISessionTimeline

	/**
	 * For shared session, we need to get the orgId and appId from the sessionDetail
	 */
	const orgId = currentOrgReducer?.orgId || sessionDetail?.orgId
	// eslint-disable-next-line no-underscore-dangle
	const appId = currentAppReducer?._id || sessionDetail?.appId
	const appType = currentAppReducer?.appType || sessionDetail?.appType || 'mobile'

	const planType = currentOrgReducer?.planType;
	const planName = currentOrgReducer?.planName;

	const loggedInFromAdmin = React.useMemo( () => {
		try {
		  const browserCookies = new Cookies();
	
		  return browserCookies.get('loggedInFromAdminDashboard');
		} catch (error) {
		  return 0;
		}
	  }, [] )

	const featureFlagsContextData = useMemo(() => ({
		appType,
		applicationId: appId,
		organizationId: orgId,
		subscriptionPlan: planType,
		subscription_plan: planType,
		subscriptionPlanName: planName,
		loggedInFromAdminDashboard: parseInt(loggedInFromAdmin, 10) || 0,
		anonymous: false, // override the default value of true
		key: 'anonymous-user', // prevent individual user tracking
	  }), [ appId, orgId, planType, planName, loggedInFromAdmin, appType])

	return (
		<FeatureFlagsProvider
			user={ featureFlagsContextData }
			// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
			clientKey={ process.env.FEATURE_FLAG_ID! }
		>
			{ children }
		</FeatureFlagsProvider>
	)

}