import { Component } from 'react'
import { connect } from 'react-redux'
import dynamic from 'next/dynamic'
import { fetchPlanHatApi } from 'redux/actions/common'
import { rollbar } from 'components/common/rollbar'
import { isProd } from 'Utils/constants/variables'

const Error = dynamic(import('pages/_error'), {
  loading: () => <p />,
  ssr: false,
})
class ErrorBoundary extends Component {
  state = {
    hasError: false,
  }
  logErrorToMyService = (error) => {
    if (error) {
      isProd && rollbar.error('PAGE CRASH ALERT!' + ' ' + error)
      this.props.fetchPlanHatApi({ action: 'Something went wrong' })
      this.setState({
        hasError: true,
      })
    }
  }
  static getDerivedStateFromError(error) {
    // Update state so the next render will show the fallback UI.
    return { hasError: true }
  }
  componentDidCatch(error, errorInfo) {
    // You can also log the error to an error reporting service
    this.logErrorToMyService(error, errorInfo)
  }
  render() {
    const { pageLevelError, errorReducer } = this.props
    if (
      this.state.hasError ||
      pageLevelError ||
      (typeof errorReducer?.message === 'string' &&
        errorReducer?.message?.includes('Network Error'))
    ) {
      // You can render any custom fallback UI
      return (
        <Error
          statusCode='custom'
        />
      )
    }
    return this.props.children
  }
}
export default connect(null, { fetchPlanHatApi })(ErrorBoundary)
