/* eslint-disable no-plusplus */
import axios from 'axios'
import { axiosInstance } from './globalInstance'

const { CancelToken } = axios
const mapApiProps = ({ apiKey, data }) => {
  const url = `${process.env.PYTHON_API_URL}/users/${apiKey}`
  const apiProps = {
      method: 'POST',
      url,
      data,
      withCredentials: true,
   }
  return apiProps
}
class UserApi {
  static async userList(appId) {
    let request = 0; let cancel;
    request++;
    if (cancel) {
      await cancel(request);
    }
    const userRes = await axiosInstance.get(
      `${process.env.API_URL}/app/${appId}/user`,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
    cancel = null;
    return userRes;
  }

  static async getUsersList(data) {
    let request = 0; let cancel;
    // source.cancel()
    request++;
    if (cancel) await cancel(request);
    const url = `${process.env.PYTHON_API_URL}/users/list`;
    const userRes = await axiosInstance.post(
        url,
        data,
        {
          withCredentials: true,
          cancelToken: new CancelToken((c) => {
            // An executor function receives a cancel function as a parameter
            cancel = c;
            request = 0;
          }),
        }
      );
    
    cancel = null;
    return userRes;
  }

  static async userDetail(payload) {
    // const sentCookies = 'token='+cookies;
    let request = 0; let cancel;
    request++;
    if (cancel) await cancel(request);
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/users/get_details`,
      data: payload,
      withCredentials: true,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        cancel = c;
        request = 0;
      }),
    });
    return response;
  }

  static async getUserSmallTable(appId, filter, page, dateRange) {
    let request = 0; let cancel;
    request++;
    if (cancel) await cancel(request);
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/app/${appId}/user/sessions`,
      data: { filter, page, dateRange },
      withCredentials: true,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        cancel = c;
        request = 0;
      }),
    });
    cancel = null;
    return response;
  }

  // delete api
  static async deleteUsersAndSessions(appId, data, type) {
  let deleteUsersSessionsCancel = null; let request = 0;
    request++;
    if (deleteUsersSessionsCancel) await deleteUsersSessionsCancel(request);
    const url = `${process.env.API_URL}/app/${appId}/${type}`;
    const response = await axiosInstance({
      method: 'DELETE',
      url,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
      cancelToken: new CancelToken((c) => {
        // An executor function receives a deleteUsersSessionsCancel function as a parameter
        deleteUsersSessionsCancel = c;
        request = 0;
      }),
    });
    deleteUsersSessionsCancel = null;
    return response;
  }

  static async locationApi(data) {
    let locationApiCancel; let locationApiRequest = 0;
    locationApiRequest++;
    if (locationApiCancel) await locationApiCancel(locationApiRequest);
    const url = `${process.env.PYTHON_API_URL_V2}/users/get_map_details`;
    const response = await axiosInstance({
      method: 'POST',
      url,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
      cancelToken: new CancelToken((c) => {
        // An executor function receives a locationApiCancel function as a parameter
        locationApiCancel = c;
        locationApiRequest = 0;
      }),
    });
    locationApiCancel = null;
    return response;
  }

  static async users_grouping_options (data) {
    const response = await axiosInstance({
      method: 'GET',
      url: `${process.env.PYTHON_API_URL}/users/grouping_dropdowns/${data.appid}`,
      withCredentials: true
    })
    return response
  }

  static async users_statistics (data) {
    const response = await axiosInstance(mapApiProps({ apiKey: 'statistics', data }))
    return response
  }

  static async top_screen_duration(data) {
    const response = await axiosInstance(mapApiProps({ apiKey: 'top_screen_duration', data }))
    return response
  }

  static async top_screen_count(data) {
    const response = await axiosInstance(mapApiProps({ apiKey: 'top_screen_count', data }))
    return response
  }

  static async top_event_stat_box(data) {
    const response = await axiosInstance(mapApiProps({ apiKey: 'top_event_stat', data }))
    return response
  }

  static async issues_stat_box(data) {
    const response = await axiosInstance(mapApiProps({ apiKey: 'issues_stat', data }))
    return response
  }
}
export default UserApi
