const initialState = {
  selectedEventField: [],
  selectedGestureField: [],
  allEvents: true,
  screenTimeLineData: {},
  isEventTriggered: false,
  selectedScreens: [],
  skipDeselectedToggle: true,
  allScreenCheckToggle: true,
  isLastSelectedScreen: { flag: false, message: '' },
  screenList: [],
  screenCategoryFlag: 'allScreens'
}

const screenTimelineReducer = (state = initialState, action) => {
  switch (action.type) {
    case 'SET_EVENT_LIST':
      return { ...state, selectedEventField: action.data }
    case 'SET_GESTURE_LIST':
      return { ...state, selectedGestureField: action.data }
    case 'SET_ALL_EVENTS':
      return { ...state, allEvents: action.data }
    case 'SET_FILTERED_TIMELINE':
      return { ...state, screenTimeLineData: action.data }
    case 'SET_EVENT_TRIGGERED':
      return { ...state, isEventTriggered: action.data }
    case 'SET_ALL_SCREENS':
      return {
        ...state, screenList: action.data
      }
    case 'SET_SELECTED_SCREEN':
      return {
        ...state, selectedScreens: action.data
      }
    case 'SKIP_DESELECTED_SCREEN':
      return {
        ...state,
        skipDeselectedToggle: action.data
      }
    case 'ALL_SCREEN_CHECK_TOGGLE':
      return {
        ...state,
        allScreenCheckToggle: action.data
      }
    case 'SCREENS_CATEGORY_FLAG':
      return {
        ...state,
        screenCategoryFlag: action.data
      }
    case 'IS_LAST_SELECTED_SCREEN':
      return {
        ...state,
        isLastSelectedScreen: action.data
      }
    case 'RESET_FILTER_DROPDOWN':
      return initialState
    default:
      return state;
  }
};

export default screenTimelineReducer;
