import { defaultDepthSunBurst } from 'components/features/navigation/constants'
import {
  SCREEN_LIST,
  LOG_OUT,
  SCREEN_FLOW_DATA,
  SCREEN_RENAME,
  CLEAR_SCREEN_BURST,
  SUN_BURST_DEPTH
} from '../../types'

export const screenReducer = (state = [], action) => {
  switch (action.type) {
    case SCREEN_LIST:
      return action.data === undefined ? state : action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}

export const screenDetailReducer = (
  state = {
    loader: false,
    data: {},
    chooseIndex: null,
    sunburstPlotGraph: [],
    selectedTab: 'sankey',
    sunBurstDepth: defaultDepthSunBurst,
    noCodeFlag: false,
    isRevampedIssuePage: false,
  },
  action
) => {
  switch (action.type) {
    case 'SCREEN_DETAIL':
      return action.data === undefined ? state : action.data;
    case SCREEN_FLOW_DATA:
      return {
        ...state,
        [action.data.keyVal]: action.data[action.data.keyVal],
      };
    case CLEAR_SCREEN_BURST:
      return {
        ...state,
        sunburstPlotGraph: [],
      };
    case SUN_BURST_DEPTH:
      return {
        ...state,
        sunBurstDepth: action.data
      }
    case 'NO_CODE_FLAG':
      return {
        ...state,
        noCodeFlag: action.data
      }
    case 'ISSUE_REVAMP':
        return {
          ...state,
          isRevampedIssuePage: action.data
        }
    case LOG_OUT:
      return [];
    default:
      return state;
  }
};

export const screenRenamedList = (state = {}, action) => {
  switch (action.type) {
    case SCREEN_RENAME:
      return action.data === undefined ? state : action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}
