import {
  format,
  formatDistanceStrict,
  subDays,
  addDays,
  intervalToDuration,
  parseISO,
} from 'date-fns';
import { utcToZonedTime } from 'date-fns-tz';

export const currentTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;

/* format date time objects in different forms */
export const getUserDate = (date, dateFormat) =>
  format(utcToZonedTime(date, ''), dateFormat);

export const getSessionDate = (date, dateFormat) => {
  const zonedDate = utcToZonedTime(date, currentTimeZone);
  return format(zonedDate, dateFormat);
};

export const getDate = (date, dateFormat) =>
  date && format(new Date(date), dateFormat);

export const getUtcDate = (date, dateFormat) => {
  if (date){
    const utcDate = utcToZonedTime(date, "UTC");
    return format(utcDate, dateFormat);
  }
}

export const getTime = (date) => format(new Date(date), 'HH:mm a');

export const getDateWithTime = (date) =>
  format(new Date(date), 'dd.MM.yyyy HH:mm a');
export const getDateMonth = (date) => date ? format(new Date(date), 'dd-MM-yyyy') : '';
export const getDateDay = (date) => format(new Date(date), 'EEEE');

export const getDateDayTime = (date) => format(new Date(date), 'EEEE hh:mm a');
export const getDateMonthDayTime = (date) =>
  format(new Date(date), 'EEE, MMM dd, hh:mm a');
export const getDateMonthDayYearTime = (date) =>
  format(new Date(date), 'MMM dd, yyyy hh:mm a');
export const getDateMonthTime = (date) =>
  format(new Date(date), 'MMM dd, yyyy');
export const getDateMonthYear = (date) =>
  format(new Date(date), 'dd MMMM, yyyy');
export const getStandardDateWithTime = (date) => {
  const dateTime = format(new Date(date), 'EEE, MMM dd, hh:mm');
  const timeFormat = format(new Date(date), 'a') === 'AM' ? 'am' : 'pm';
  return `${dateTime} ${timeFormat}`;
};
export const getStandardDateWithTime24 = (date) => {
  const dateTime = format(new Date(date), 'MMMM dd, yyyy, HH:mm');
  return `${dateTime}`;
};

export const getDateMonthDay = (date) => format(new Date(date), 'MMM dd');

export const getDifferenceFromNow = (date) =>
  `${formatDistanceStrict(parseISO(date), new Date())} ago`;

export const formattedTime = (num) => {
  const attachZero = (t) => `${t < 10 ? `0${t}` : t}`;
  const { hours, minutes, seconds } = intervalToDuration({
    start: 0,
    end: num * 1000,
  });
  const days = Math.floor(num / (24 * 60 * 60));
  let formatted;
  if (num > -1) {
    if (num < 60) formatted = `0:${attachZero(seconds)} min`;
    else if (num >= 60 && num < 3600)
      formatted = `${attachZero(minutes)}:${attachZero(seconds)} min`;
    else if (num > 3600 && num < 86400)
      formatted = `${attachZero(hours)}:${attachZero(minutes)}:${attachZero(
        seconds
      )} h`;
    else if (num >= 86400)
      formatted = days <=1 ? `${days} day` : `${days} days`;
  } else formatted = '-';
  return formatted;
};

export const getPrefix = (num) => {
  let prefix;
  if (num < 120) prefix = 'sec';
  else if (num > 120 && num < 3600) prefix = 'min';
  else if (num > 3600 && num < 86400) prefix = 'hr';
  else prefix = 'day';
  return prefix;
};

export const subtractDaystoDate = (date, number, dateFormat) => {
  const subDate = subDays(new Date(date), number);
  return format(subDate, dateFormat);
};

export const addDaystoDate = (date, number, dateFormat) =>
  format(addDays(new Date(date), number), dateFormat);

/* to get the time difference in years, months , days, hours, minutes and seconds */
const intervals = [
  { label: 'year', seconds: 31536000 },
  { label: 'month', seconds: 2592000 },
  { label: 'day', seconds: 86400 },
  { label: 'hour', seconds: 3600 },
  { label: 'minute', seconds: 60 },
  { label: 'second', seconds: 1 },
];
export const convertDateTime = (seconds) => {
  if (seconds && seconds > 0) {
    const interval = intervals.find((i) => i.seconds < seconds);
    const count = Math.round(seconds / interval?.seconds);
    return `${count} ${interval?.label}${count !== 1 ? 's' : ''} ago`;
  }
  return 'Just now';
};
export const getOffsetTimeFromUTC = (_) => {
  const offsetTime = format(new Date(), 'zzz');
  return offsetTime.includes('+')
    ? `+${offsetTime.split('+')[1]}`
    : offsetTime.includes('-')
    ? `-${offsetTime.split('-')[1]}`
    : offsetTime;
};

export const formatDate = (date, formatter) =>
  format(utcToZonedTime(date, ''), formatter);

export const readableTimeFormatter = (num) => {
  const { years, months, days, hours, minutes, seconds } = intervalToDuration({
    start: 0,
    end: num * 1000,
  });
  let formatted;
  if (num > -1) {
    if (num < 60) formatted = `${num.toFixed(2)}s`;
    else if (years)
      formatted = `${years}y ${
        months
          ? `${months}m`
          : days
          ? `${days}d`
          : hours
          ? `${hours}h`
          : minutes
          ? `${minutes}min`
          : `${seconds}s`
      }`;
    else if (months)
      formatted = `${months}m ${
        days
          ? `${days}d`
          : hours
          ? `${hours}h`
          : minutes
          ? `${minutes}min`
          : `${seconds}s`
      }`;
    else if (days)
      formatted = `${days}d ${
        hours ? `${hours}h` : minutes ? `${minutes}min` : `${seconds}s`
      }`;
    else if (hours)
      formatted = `${hours}h ${minutes ? `${minutes}min` : `${seconds}s`}`;
    else if (minutes)
      formatted = `${minutes}min ${seconds ? `${seconds}s` : ''}`;
  } else formatted = '-';
  return formatted;
};

export const formatPlayerTime = (num) => {
  const attachZero = (t) => `${t < 10 ? `0${t}` : t}`;
  const { hours, minutes, seconds } = intervalToDuration({
    start: 0,
    end: num * 1000,
  });
  let formatted;
  if (num > -1) {
    if (num < 1) {
      const milliseconds = num * 1000;
      formatted = `0:0${String(milliseconds).slice(0, 2)}`;
    } else if (num >= 1 && num < 60) formatted = `0:${attachZero(seconds)}`;
    else if (hours)
      formatted = `${hours}:${attachZero(minutes)}:${attachZero(seconds)}`;
    else if (hours === 0 && minutes)
      formatted = `${minutes}:${attachZero(seconds)}`;
  } else formatted = '-';
  return formatted;
};

export const getDateDifferenceString = ({ dateSegment, dateRangeName }) => {
  const dateNow = new Date();
  const { value: {lower, upper} } = dateSegment || {};
  const toFormatted = getDateMonthDay(upper);
  const fromFormatted = getDateMonthDay(lower);
  const dateFormatString = `${fromFormatted} - ${toFormatted}, ${dateNow.getFullYear()} ${`${
    dateRangeName && dateRangeName !== 'Custom'
      ? `(${dateRangeName.replace('Last', '').trim()})`
      : ''
  }`} `;
  return dateFormatString;
};

