const getTimezone = () => ({
  timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  timezoneOffset: new Date().getTimezoneOffset(),
})

export const getTimezoneOffset = ( timeZone = 'UTC', date = new Date() ) => {
  const utcDate = new Date( date.toLocaleString( 'en-US', { timeZone: 'UTC' } ) )
  const tzDate = new Date( date.toLocaleString( 'en-US', { timeZone } ) )
  return ( utcDate.getTime() - tzDate.getTime() ) / 6e4;
}

export const adjustDateTimezoneToLocal = ( date, tzString ) => {
  const useDate = ( typeof date === 'string' ? new Date( date ) : date )
  const updatedTzString = tzString?.replace(/\s/g, '+'); // fix to replace spaces with + for tzString 
  return new Date(
    useDate.getTime()
    + ( getTimezone().timezoneOffset - getTimezoneOffset( updatedTzString ) ) * 60_000,
  )
}

export const convertDateToTimezone = ( date, tzString) => {
  const useDate = ( typeof date === 'string' ? new Date( date ) : date )
  return new Date(
    useDate.getTime()
    + ( getTimezoneOffset( tzString ) - getTimezone().timezoneOffset ) * 60_000,
  )
};

export const getLocalDateString = (date) => new Date( date ).toLocaleDateString( 'en-US', {
  month: 'short',
  year: 'numeric',
  day: '2-digit',
});

export const getDisplayRangeDate = (date, tz='UTC') => {
  const adjustedDate = adjustDateTimezoneToLocal(date, tz); // timezone can be dynamic - default its UTC
  return getLocalDateString(adjustedDate);
};

export const getFormattedTime = (seconds) => {
  if (seconds < 60) {
    return `${seconds} second${seconds !== 1 ? 's' : ''}`;
  }

  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return `${minutes} minute${minutes !== 1 ? 's' : ''}`;
  }

  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return `${hours} hour${hours !== 1 ? 's' : ''}`;
  }

  const days = Math.floor(hours / 24);
  if (days < 365) {
    return `${days} day${days !== 1 ? 's' : ''}`;
  }

  const weeks = Math.floor(days / 7);
  return `${weeks} week${weeks !== 1 ? 's' : ''}`;

};

export const formatTimeSince = (timestamp) => {
  if (!timestamp) return '';

  const seconds = Math.floor((Date.now() - timestamp) / 1000);

  if (seconds < 60) {
    return 'just now';
  }

  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return `${minutes} min ago`;
  }

  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return `${hours} hr ago`;
  }

  const days = Math.floor(hours / 24);
  if (days < 365) {
    return `${days} day ago`;
  }

  const years = (days / 365).toFixed(1);
  return `${years} year ago`;
};

export const parseUtcTimestampToMs = (utcTimestamp) => {
  if (!utcTimestamp) return Date.now()
  const isoString = `${utcTimestamp.replace(' ', 'T')}Z`
  return parseISO(isoString).getTime()
}

const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sept', 'Oct', 'Nov', 'Dec']
const DAYS_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

export const formatDateWithTime = (dateStr) => {
  const d = new Date(dateStr)
  const month = MONTHS_SHORT[d.getMonth()]
  const day = d.getDate()
  const year = d.getFullYear()
  const dayName = DAYS_SHORT[d.getDay()]
  let hours = d.getHours()
  const minutes = d.getMinutes().toString().padStart(2, '0')
  const ampm = hours >= 12 ? 'pm' : 'am'
  hours = hours % 12 || 12

  return {
    date: `${month} ${day}, ${year}`,
    time: `${dayName}, ${hours}:${minutes} ${ampm}`,
  }
}