import axios from 'axios';
import Cookies from 'universal-cookie';
import Router from 'next/router';
import mixpanel from 'mixpanel-browser';
import { isLocal } from 'Utils/constants/variables';
import { tokenRefreshManager } from './tokenRefreshManager';

const cookies = new Cookies();

const handleUnAuthorizedError = (status) => {
  if (status === 401) {
    tokenRefreshManager.clearLoggedInCookie();
    localStorage.clear();
    sessionStorage.clear();
    typeof window !== 'undefined' &&
      window.Intercom &&
      window.Intercom('shutdown');
    mixpanel?.persistence?.clear();
    Router.push('/logout');
  }
};

export const axiosInstance = axios.create();

// TODO: to be removed function as we don't maintain it anymore
export const trackEvent = async (response, resCurrentTime) => {
  if (isLocal) return;
  const apiResponseTime = () => {
    let time;
    const requestStartedAt = response?.config?.meta?.requestStartedAt;
    return time;
  };
};

axiosInstance.interceptors.request.use(
  async (config) => {
    // Proactively refresh token before it expires
    const skipRefreshFor = ['/refresh-token', '/login', '/signup', '/reset-password', '/google-login', '/google-sign-in'];
    const shouldSkipRefresh = skipRefreshFor.some(path => config.url?.includes(path));
    if (!shouldSkipRefresh) {
      await tokenRefreshManager.refreshIfNeeded();
    }

    try {
      localStorage.setItem('apiCalledTime', Math.floor(Date.now() / 1000));
    } catch (err) {
      // silent fail
    }
    const newConfig = { ...config };
    const tokenValue = cookies.get('CSRF-Token');
    const authToken = cookies.get('token');
    // newConfig.metadata = { startTime: Math.floor(Date.now() / 1000) }
    newConfig.meta = config.meta || {};
    newConfig.meta.requestStartedAt = new Date().getTime();
    const apiUrl = newConfig?.url;
    if (apiUrl.indexOf('dashboardapi') >= 0) {
      newConfig.headers = { 'X-CSRF-Token': tokenValue };
    }
    // auth
    if ((apiUrl.includes(`${process.env.AUTH_API_URL}`) || apiUrl.includes(`${process.env.SUBSCRIPTION_URL}`) || apiUrl.includes(`${process.env.IDH_API_URL}`)) && authToken) {
      newConfig.headers = { Authorization: `Bearer ${authToken}` };
    }
    return newConfig;
  },
  (error) => Promise.reject(error)
);

axiosInstance.interceptors.response.use(
  async (response) => {
    try {
      localStorage.setItem('apiCalledTime', null);
    } catch (err) {
      // silent fail
    }

    return response;
  },
  async (error) => {
    // Fallback: handle 401s that slip through (clock skew, server-side revocation)
    if (error?.response?.status === 401) {
      const requestUrl = error.config?.url || '';

      if (requestUrl.includes('/refresh-token')) {
        handleUnAuthorizedError(401);
        return Promise.reject(error);
      }

      const authPages = ['/login', '/signup', '/logout', '/reset-password', '/invite'];
      if (typeof window !== 'undefined') {
        const { pathname } = window.location;
        if (authPages.some(page => pathname.includes(page))) {
          handleUnAuthorizedError(401);
          return Promise.reject(error);
        }
      }

      return tokenRefreshManager.handle401(error, axiosInstance);
    }

    return Promise.reject(error);
  }
);

class eventTrackApi {
  static async eventTrackPageView(data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.IDH_API_URL}/data-hub/send-event/`,
      data,
      withCredentials: true,
      responseType: 'json',
    });
    return response;
  }

  static async publicEventTrackPageView(data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.IDH_API_URL}/data-hub/send-event-public/`,
      data,
      withCredentials: true,
      responseType: 'json',
    });
    return response;
  }
}
export default eventTrackApi;