/* eslint-disable import/prefer-default-export */
import {
  FILTER_DISPLAY_BAR_FLAG,
  MEGA_DROPDOWN_FLAG,
  RESET_ALL_STATES,
  SELECTED_ATTRIBUTE_PROPS,
  MEGA_DROPDOWN_FLAG_BOTTOM,
} from 'Utils/constants/reduxActionTypes/megaFilter'
import { LOG_OUT } from '../../types'

const initialState = {
  filterBarVisible: false,
  megaDropdownVisible: false,
  saveSegmentVisible: false,
  clickedSegment: {},
  selectedAttributeProps: {},
  megaBottomDropdownVisible: false,
  segmentModal: {},
}

export const megaFilterReducer = (state = initialState, action) => {
  switch (action.type) {
    case FILTER_DISPLAY_BAR_FLAG:
      return { ...state, filterBarVisible: action.filterBarVisible }
    case MEGA_DROPDOWN_FLAG:
      return { ...state, megaDropdownVisible: action.megaDropdownVisible }
    case MEGA_DROPDOWN_FLAG_BOTTOM:
      return { ...state, megaBottomDropdownVisible: action.megaBottomDropdownVisible }
    case SELECTED_ATTRIBUTE_PROPS:
      return {
        ...state,
        selectedAttributeProps: action.data,
      }
    case RESET_ALL_STATES:
      return {
        ...state,
        filterBarVisible: false,
        megaDropdownVisible: false,
        saveSegmentVisible: false,
        selectedAttributeProps: {},
        segmentModal: {},
      }
    case LOG_OUT:
      return []
    default:
      return state
  }
}
