import { LOG_OUT } from '../../types'

const initialState = {
    sso: {
      ssoUrl: '',
      entityId: '',
      certificate: '',
      spEntityId: '',
      spAcsUrl: '',
      loginUrl: null
    },
    error: '',
    ssoEnabled: false
  }
  const ssoReducer = (state = initialState, action) => {
    switch (action.type) {
      case 'GET_SSO_CONFIG':
        return { ...state, sso: action.data }
      case 'GET_SSO_CONFIG_ERR':
        return { ...state, error: action.data, sso: {} }
      case 'CLEAR_SSO_CONFIG':
        return { ...state, sso: action.data, error: '' }
      case 'SET_SINGLE_SIGN_ON':
        return { ...state, ssoEnabled: action.data, sso: {} }
      case LOG_OUT:
        return []
      default:
        return state
    }
  }
  export default ssoReducer;
