/* eslint-disable class-methods-use-this */
import axios from 'axios';
import Router from 'next/router';
import mixpanel from 'mixpanel-browser';

const DEFAULT_ACCESS_TOKEN_EXPIRY_MS = 10 * 60 * 1000; // 10 minutes fallback
const REFRESH_BUFFER_MS = 30 * 1000; // refresh 30s before expiry
const STORAGE_KEY = 'tokenExpiresAt';
const POST_REFRESH_DELAY_MS = 200;
const LOGGED_IN_COOKIE = 'logged_in';
const LOGGED_IN_MAX_AGE_SECONDS = 30 * 24 * 60 * 60; // 30 days

const delay = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });

class TokenRefreshManager {
  constructor() {
    this.isRefreshing = false;
    this.refreshPromise = null;
    this.tokenExpiresAt = null;

    // Restore from localStorage if available
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.tokenExpiresAt = parseInt(stored, 10);
      }
    }
  }

  setLoggedInCookie = () => {
    if (typeof document !== 'undefined') {
      document.cookie = `${LOGGED_IN_COOKIE}=1; path=/; max-age=${LOGGED_IN_MAX_AGE_SECONDS}`;
    }
  };

  clearLoggedInCookie = () => {
    if (typeof document !== 'undefined') {
      document.cookie = `${LOGGED_IN_COOKIE}=; path=/; max-age=0`;
    }
  };

  /**
   * @param {number|null} expiresAt - Unix timestamp (seconds) from backend's expires_at field
   */
  setTokenExpiry = (expiresAt) => {
    this.tokenExpiresAt = expiresAt
      ? expiresAt * 1000 // convert seconds to ms
      : Date.now() + DEFAULT_ACCESS_TOKEN_EXPIRY_MS; // fallback: 10 minutes from now
    try {
      localStorage.setItem(STORAGE_KEY, String(this.tokenExpiresAt));
    } catch (err) {
      // silent fail
    }
  };

  isTokenExpiringSoon = () => {
    if (!this.tokenExpiresAt) {
      this.setTokenExpiry(null);
      return false;
    }
    return Date.now() > this.tokenExpiresAt - REFRESH_BUFFER_MS;
  };

  isAuthPage = () => {
    if (typeof window === 'undefined') return false;
    const { pathname, search } = window.location;
    const urlParams = new URLSearchParams(search);
    const parentType = urlParams.get('parentType');
    const authPages = ['/login', '/signup', '/logout', '/reset-password', '/invite', '/invitation/', '/dashboard/org/', '/onboardForm', '/error', '/share/', '/quote/', '/token/', '/secret/', '/welcome/first_visit'];
    const authParentTypes = ['login', 'signup', 'signup_offer', 'reset_password', 'setup_password', 'resend_activation'];

    return authPages.some(page => pathname.includes(page)) || (parentType && authParentTypes.includes(parentType));
  };

  refreshToken = async () => {
    try {
      const url = `${process.env.AUTH_API_URL}/refresh-token`;

      const response = await axios.post(
        url,
        {},
        {
          withCredentials: true,
          timeout: 5000,
        }
      );

      if (response.status === 200) {
        if (process.env.NODE_ENV === 'development') {
          // eslint-disable-next-line no-console
          console.log('[TokenRefresh] Access token refreshed successfully');
        }
        this.setTokenExpiry(response.data?.data?.expires_at);
        this.setLoggedInCookie();
        return true;
      }

      return false;
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        // eslint-disable-next-line no-console
        console.error('[TokenRefresh] Failed to refresh token:', error.message);
      }

      // If refresh-token returns 401, the refresh token has expired
      if (error?.response?.status === 401) {
        this.handleRefreshFailure();
      }

      return false;
    }
  };

  /**
   * Main method — call before any API request.
   * If token is expiring soon, triggers a refresh and waits.
   * If refresh is already in progress, waits for it.
   * Otherwise returns immediately.
   * @returns {Promise<boolean>} - True if a NEW refresh was performed and succeeded, false otherwise
   */
  refreshIfNeeded = async () => {
    // Token refresh needs the browser cookie jar, localStorage and next/router.
    // During SSR this singleton is shared by every request in the Node process,
    // so it must never attempt a refresh there.
    if (typeof window === 'undefined') return false;

    // If a refresh is already in progress, wait for it
    if (this.isRefreshing && this.refreshPromise) {
      await this.refreshPromise;
      await delay(POST_REFRESH_DELAY_MS);
      return false; // No NEW refresh happened
    }

    // If token is not expiring soon, nothing to do
    if (!this.isTokenExpiringSoon()) return false; // No refresh needed

    if (this.isAuthPage()) return false; // Can't refresh on auth page

    // Start refresh with lock
    this.isRefreshing = true;

    this.refreshPromise = this.refreshToken()
      .then(async (success) => {
        return success;
      })
      .finally(() => {
        this.isRefreshing = false;
        this.refreshPromise = null;
      });

    const didRefresh = await this.refreshPromise;
    await delay(POST_REFRESH_DELAY_MS);
    return didRefresh; // Return TRUE if refresh succeeded
  };

  /**
   * Fallback 401 handler for the response interceptor.
   * Attempts one refresh + retry when a 401 slips through.
   */
  handle401 = async (error, axiosInstance) => {
    if (typeof window === 'undefined') return Promise.reject(error);

    const originalRequest = error.config;

    if (originalRequest.isRetry) {
      return Promise.reject(error);
    }

    originalRequest.isRetry = true;

    // If refresh is already in progress, wait then retry
    if (this.isRefreshing && this.refreshPromise) {
      try {
        await this.refreshPromise;
        return axiosInstance.request(originalRequest);
      } catch (refreshError) {
        return Promise.reject(refreshError);
      }
    }

    this.isRefreshing = true;

    this.refreshPromise = this.refreshToken()
      .then(async (success) => {
        if (success) await delay(POST_REFRESH_DELAY_MS);
        return success;
      })
      .finally(() => {
        this.isRefreshing = false;
        this.refreshPromise = null;
      });

    try {
      const success = await this.refreshPromise;
      if (success) {
        return axiosInstance.request(originalRequest);
      }
      return Promise.reject(error);
    } catch (refreshError) {
      return Promise.reject(refreshError);
    }
  };

  handleRefreshFailure = () => {
    this.clearLoggedInCookie();
    try {
      localStorage.clear();
    } catch (err) {
      // silent fail
    }

    if (typeof window !== 'undefined' && window.Intercom) {
      window.Intercom('shutdown');
    }

    if (mixpanel?.persistence) {
      mixpanel.persistence.clear();
    }

    Router.push('/logout');
  };

  /** Called after login to start tracking token expiry
   * @param {number|null} expiresAt - Unix timestamp (seconds) from login response's expires_at
   */
  start = (expiresAt) => {
    this.setTokenExpiry(expiresAt);
    this.setLoggedInCookie();
  };

  /** Called on logout to clear state */
  stop = () => {
    this.isRefreshing = false;
    this.refreshPromise = null;
    this.tokenExpiresAt = null;
    this.clearLoggedInCookie();
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (err) {
      // silent fail
    }
  };
}

export const tokenRefreshManager = new TokenRefreshManager();

export default TokenRefreshManager;
