import { FETCH_QUOTE_DETAIL, QUOTE_ADD_PLAN, QUOTE_ADD_PLAN_FAILURE, QUOTE_FETCH_FAILURE } from '../../types'

export const quoteReducer = (state = {}, action) => {
  switch (action.type) {
    case FETCH_QUOTE_DETAIL:
    case QUOTE_ADD_PLAN:
      return action.data === undefined ? state : action.data

    case QUOTE_FETCH_FAILURE:
    case QUOTE_ADD_PLAN_FAILURE:
      return action.error === undefined ? state : action.error

    default:
      return state
  }
}
