import { LOG_OUT, USER_FILTER_PROPERTIES, SHOW_USER_FILTER_MENU, USER_FILTER_LIST, USER_SELECTED_SEGMENT } from '../../types'

export const userFilterList = (state = [], action) => {
  switch (action.type) {
    case USER_FILTER_LIST:
      return action.data === undefined ? state : action.data
    case LOG_OUT:
      return []
    default:
      return state
  }
}

