export const useSessionTimeLine = () => {
  const {
    sessionDetail,
    setSessionDetail,
    rewind,
    currentScreen,
    currentGesture,
    currentTimeRef,
    sessionGestures,
    sessionEvents,
    sessionNocodeEvents,
    sessionBugInfo,
    nearestSession,
    sessionLogs,
    setSessionGestures,
    sessionQueriesToInvalidate,
    setSessionQueriesToInvalidate,
    setSessionEvents,
    setSessionNocodeEvents,
    setSessionBugInfo,
    setNearestSession,
    setSessionLogs,
    videoLimitPopup,
    setVideoLimitPopup,
  } = useContext(SessionsTimelineDataContext);

  const isWebSession = React.useMemo( () => {
    return sessionDetail?.device?.platform === 3;
  }, [sessionDetail] );

  const sessionDetailScreens = React.useMemo(
    () =>
      new Set(
        (sessionDetail?.screenTimeline?.activities || []).map(
          ({ activityName }) => activityName
        )
      ),
    [sessionDetail]
  );

  return useMemo(
    () => ({
      sessionDetail,
      sessionDetailScreens,
      setSessionDetail,
      rewind,
      currentScreen,
      currentGesture,
      currentTimeRef,
      sessionGestures,
      sessionEvents,
      sessionNocodeEvents,
      sessionBugInfo,
      nearestSession,
      sessionLogs,
      setSessionGestures,
      setSessionEvents,
      setSessionNocodeEvents,
      sessionQueriesToInvalidate,
      setSessionQueriesToInvalidate,
      setSessionBugInfo,
      setNearestSession,
      setSessionLogs,
      videoLimitPopup,
      setVideoLimitPopup,
      isWebSession,
    }),
    [
      sessionDetail,
      sessionDetailScreens,
      setSessionDetail,
      rewind,
      currentTimeRef,
      currentGesture,
      currentScreen,
      sessionGestures,
      sessionEvents,
      sessionNocodeEvents,
      sessionBugInfo,
      nearestSession,
      sessionLogs,
      setSessionEvents,
      setSessionNocodeEvents,
      sessionQueriesToInvalidate,
      setSessionQueriesToInvalidate,
      setSessionGestures,
      setSessionBugInfo,
      setNearestSession,
      setSessionLogs,
      videoLimitPopup,
      setVideoLimitPopup,
      isWebSession,
    ]
  );
};

