export const appFilter = (state = {...initialState}, action) => {
  switch (action.type) {
    case ALL_FILTER:
      return action.data === undefined ? state : action.data;
    case ADD_FILTER_SEGMENT:
      return {
        ...state,
        [action.data.page]: {
          ...state[action.data.page],
          segment:  Array.isArray(action.data.data) ? [...action.data.data] : []
        },
      }; 
    case SET_ACTIVITY_FILTER:
      return {
        ...state,
        [action.data.page]: {
          ...state[action.data.page],
          activityFilterList: action.data.data,
        },
      };
      
    case GET_DATE_SEGMENT: {
      const dateSegmentIsInitial = action.data.initial || false
      const actionCopy = { ...action }
      delete actionCopy.data.initial
      return {
        ...state,
        dateSegmentIsInitial,
        dateSegment: actionCopy.data,
      };
    }
    case SET_PAGE_FILTER_TABLE:
      return {
        ...state,
        dateSegment: {
          ...state.dateSegment,
          table: action.table,
        },
      };
    case SET_SAVED_SEGMENT_LIST:
      return {
        ...state,
        [action.data.page]: {
          ...state[action.data.page],
          segmentList: [...action.data.data],
        },
      };
    case FILTER_MENU_TOGGLE:
      return {
        ...state,
        filterMenuVisible: action.data
      }
    case GET_ATTRIBUTE_PROPERTIES:
      return {
        ...state,
        fetchProperty: {
          ...state.fetchProperty,
          [action.data.attribute]: {
            data: action.data.data,
          },
        },
      };
    case RESET_APP_FILTER_STATES:
      return { ...initialState };
    case LOG_OUT:
      return [];
    default:
      return state;
  }
}
