import axios from 'axios';
import { getCsrf } from 'redux/actions/common';
import v2ApiList from 'Utils/constants/v2ApiList';
import { axiosInstance } from './globalInstance';

const { CancelToken } = axios;
const alphabet = '123456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ';
const base = alphabet.length;

let cancel = null
let request = 0
let sunBurstCancel = 0
let cancelOverview = null;
let requestOverview = 0;
const getURLType = (type) => `${v2ApiList.indexOf(type) > -1 ? process.env.PYTHON_API_URL_V2 : process.env.PYTHON_API_URL}/${type}`;
