  static async getOriginalUrl(id, type, appid) {
    let ids;
    if (id.length === 24) {
      ids = id;
    } else {
      ids = await this.decode(id);
    }
     // Previously the short url api was served via the php dashbaord api endpoint.
      // with the trino release we've also migrated this endpoint to the data_visualization endpoint .
      // short url usage 
         // URL is generated by the session verify server when SDK request for the verify server. 
         // This url only has sessionid on the path 
         // User should be redirected to either session reply or user details based on the type.
         // type value 'd' and 'r' is depricated. 
         // current type are 's' and 'u'
    // Runs during SSR (pages/dashboard.js getInitialProps) against a public endpoint,
    // so use plain axios: axiosInstance's token-refresh interceptors assume a browser.
    return axios
      .post(
        `${process.env.PYTHON_API_URL_V2}/sessions/shortify`,
        { id: ids, type, appid }
      )
      .then((res) => { return res.data})
      .catch((err) => { return err});
  }

  static encode(num) {
    let encoded = '';
    while (num) {
      const remainder = num % base;
      num = Math.floor(num / base);
      encoded = alphabet[remainder]
        ? alphabet[remainder].toString()
        : `${encoded}`;
    }
    return encoded;
  }

  static decode(str) {
    let decoded = 0;
    while (str) {
      const index = alphabet.indexOf(str[0]);
      const power = str.length - 1;
      decoded += index * Math.pow(base, power);
      str = str.substring(1);
    }
    return decoded;
  }

