  static async pythonWithCancelApi(payload, type) {
    const data = payload
    request++;
    if (cancel)
      await cancel(request);
    const url = getURLType(type);
    data.output_format = 'csv'
    const response = await axiosInstance({
      method: 'POST',
      url,
      data,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 400;
      },
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
      cancel = c
      request = 0
      })
    })
    cancel = null
    return response
  }

  static async sunBurstCancelApi (data, type) {
    request++
    if (sunBurstCancel) {
      await sunBurstCancel(request)
    }
    const url = `${process.env.PYTHON_API_URL_V2}/${type}`
    const response = await axiosInstance({
      method: 'POST',
      url,
      data,
      responseType: 'json',
      withCredentials: true,
      validateStatus (status) {
        return status >= 200 && status < 400
      },
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        sunBurstCancel = c
      request = 0
      })
    })
    sunBurstCancel = null
    return response
  }

  static async pythonWithCancelOverviewApi (data, type) {
    requestOverview++
    if (cancelOverview) {
      await cancelOverview(requestOverview);
    }
    const url = getURLType(type);
    const response = await axiosInstance({
      method: 'POST',
      url,
      data,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        cancelOverview = c;
        requestOverview = 0;
      }),
    });
    cancelOverview = null;
    return response;
  }

