import { currentTimeZone } from 'Utils/DateConversion/dateConversionUtils'
import {
  STATISTICS,
  STATS_GRAPH,
  LOG_OUT,
  DEFAULT_STATS_LIST,
  EVENTS_PROPERTY_LIST,
} from '../../types'

const initialState = {
  periodGroupbyVal: {
    table: 'event',
    attribute: 'event_recorded_before',
    operator: 'lt',
    value: 1209600,
    display: 'Last 14 days',
  },
  eventDropValues: {
    attribute: 'event_count',
    type: 'count',
    table: 'event',
    operator: '',
    display: 'events',
  },
  grpByVal: [
    {
      table: 'event',
      attribute: 'event_period_day',
      tooltip: 'Day on which event was recorded.',
      period: 86400,
      display: 'day',
      time_zone_offset: currentTimeZone
    },
    {
      display: 'event name',
      type: 'str',
      tooltip: 'Assigned name of event.',
      table: 'event',
      attribute: 'eventname',
    },
  ],
  graphSelectedVal: {},
}
export const statisticsReducer = (state = initialState, action) => {
  switch (action.type) {
    case STATISTICS:
      return action.data ? action.data : state
    case STATS_GRAPH:
      return {
        ...state,
        graphData: action.data.graphData,
      }
    case DEFAULT_STATS_LIST:
      return {
        ...state,
        dropdownData: action.data.dropdownData,
      }
    case EVENTS_PROPERTY_LIST:
      return {
        ...state,
        propertyList: action.data.propertyList,
      }
    case LOG_OUT:
      return {}
    default:
      return state
  }
}
